package com.wenwen.ai.cohort;
import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
/** 显式单次合成真实模型；不启动peer、不输出wire/key。 */
class DeepSeekChatReceptionIT extends ChatHttpFixture {
    static ch.qos.logback.classic.Level oldLevel;
    DeepSeekChatReceptionIT(){realModel=true;chatProperties.put("ra.ai.chat.clinical-outbound-approved","true");chatProperties.put("ra.ai.fm-evidence.json",ConfiguredFmHttpTest.configuration("synthetic-fm-v1",0));chatProperties.put("ra.ai.drug-dictionary.json",ConfiguredFmHttpTest.drugConfiguration());chatProperties.put("ra.ai.chat.synthetic-loopback","false");chatProperties.put("ra.ai.chat.model","deepseek-flash");chatProperties.put("ra.ai.chat.proxy-mode","system");}
    @BeforeAll static void approve(){assertEquals("true",System.getenv("RA_TEST_DEEPSEEK_SYNTHETIC"));assertEquals("deepseek-flash",System.getenv("DEEPSEEK_MODEL"));assertNotNull(System.getenv("RA_AI_API_KEY"));ch.qos.logback.classic.Logger root=(ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME);oldLevel=root.getLevel();root.setLevel(ch.qos.logback.classic.Level.WARN);}
    @AfterAll static void logging(){if(oldLevel!=null)((ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME)).setLevel(oldLevel);}
    @Test void realAggregateQuestionSelectsBackendTargetFacts()throws Exception {
        assertNull(peer);assertTrue(context.getBean(com.wenwen.ai.scope.PrincipalProvider.class) instanceof com.wenwen.ai.scope.SessionPrincipalProvider);String before=digest();long started=System.nanoTime();String timestamp=java.time.Instant.now().toString();
        org.springframework.test.web.servlet.MvcResult response=request(body("ALL",null,"当前范围的DAS28-CRP达标率是多少？请说明有效人数和未知人数。"));JsonNode envelope=json.readTree(response.getResponse().getContentAsByteArray()),d=envelope.path("data");
        System.out.println("P05a single_attempt=1 timestamp="+timestamp+" source_hash="+System.getProperty("ra.chat.source-hash","unrecorded")+" model=deepseek-flash category=SYNTHETIC_AGGREGATE status="+response.getResponse().getStatus()+" outcome="+(d.isNull()?envelope.path("code").asText():d.path("status").asText())+" elapsed_ms="+java.util.concurrent.TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-started));
        assertEquals(200,response.getResponse().getStatus());assertTrue(envelope.path("success").asBoolean());assertEquals("AI",d.path("engine").asText());assertEquals("ANSWER",d.path("status").asText());assertEquals(response.getResponse().getHeader("X-Trace-Id"),d.path("meta").path("traceId").asText());assertEquals("deepseek-flash",d.path("meta").path("modelVersion").asText());assertEquals(6,d.path("scope").path("n").asInt());assertTrue(d.path("facts").size()>=1&&d.path("facts").size()<=4);JsonNode target=fact(d,"TARGET_RATE").path("data");assertEquals(0,new BigDecimal(".4").compareTo(target.path("value").decimalValue()));assertEquals(2,target.path("meta").path("numerator").asInt());assertEquals(5,target.path("meta").path("denominator").asInt());assertEquals(1,target.path("meta").path("unknownN").asInt());assertEquals("ANSWER",audit(d.path("auditRef").asText()).get("outcome"));assertEquals(1,count("ra_ai_chat_audit"));assertEquals(before,digest());assertEquals(0,count("ra_ai_analysis_run"));networkExited();auditExited();
    }
    @Test void realVisitQuestionSelectsBackendMeasurements()throws Exception {
        patientRows();assertNull(peer);assertTrue(context.getBean(com.wenwen.ai.scope.PrincipalProvider.class) instanceof com.wenwen.ai.scope.SessionPrincipalProvider);String before=digest(),timestamp=java.time.Instant.now().toString();long start=System.nanoTime();
        String body=json.writeValueAsString(com.wenwen.vo.AiCohortVo.object("scope",com.wenwen.vo.AiCohortVo.object("kind","PATIENT","patientId","1","visitId","1001"),"question","请说明本次访视记录的DAS28-CRP和CRP数值及其来源。"));org.springframework.test.web.servlet.MvcResult response=request(body);JsonNode envelope=json.readTree(response.getResponse().getContentAsByteArray()),d=envelope.path("data");
        System.out.println("P05b single_attempt=1 timestamp="+timestamp+" source_hash="+System.getProperty("ra.chat.source-hash","unrecorded")+" model=deepseek-flash category=SYNTHETIC_PATIENT_VISIT status="+response.getResponse().getStatus()+" outcome="+(d.isNull()?envelope.path("code").asText():d.path("status").asText())+" elapsed_ms="+java.util.concurrent.TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start));
        assertEquals(200,response.getResponse().getStatus());assertTrue(envelope.path("success").asBoolean());assertEquals("ANSWER",d.path("status").asText());assertEquals("AI",d.path("engine").asText());assertEquals("1001",d.path("scope").path("visitId").asText());JsonNode f=fact(d,"VISIT_MEASUREMENTS"),m=f.path("data").path("metrics");assertEquals(4.11,m.path("das28Crp").path("value").asDouble());assertEquals(20,m.path("crp").path("value").asInt());assertEquals("1001",m.path("crp").path("sourceVisitId").asText());assertEquals("1001",f.path("evidence").path("sourceVisits").get(0).path("visitId").asText());assertEquals("PATIENT",audit(d.path("auditRef").asText()).get("scope_kind"));assertEquals("ANSWER",audit(d.path("auditRef").asText()).get("outcome"));assertEquals(1,count("ra_ai_chat_audit"));assertEquals(before,digest());assertEquals(0,count("ra_ai_analysis_run"));networkExited();auditExited();
    }

}
